/* Archivio domande, lezioni 01–09. Q.add(lezione, argomento, domanda, [GIUSTA, errata, errata, errata], spiegazione, {p:1 se la prof ne ha parlato})
   Regola di scrittura: le quattro opzioni hanno lunghezza simile (la spiegazione va nel campo «perché»), nessun «tutte le precedenti». */
(function (G) {
  'use strict';
  var F = G.Fisio, Q = F.quiz, A = Q.add;

  // ======================================================================= 01 — Omeostasi e controllo
  A('01', 'Stato stazionario', 'Dal punto di vista termodinamico, una cellula viva si trova in…', ['uno stato stazionario di non-equilibrio', 'uno stato di equilibrio con l\'ambiente', 'uno stato di massima entropia interna', 'uno stato di equilibrio solo elettrico'], 'La vita richiede gradienti ionici e di concentrazione mantenuti con consumo di energia. L\'equilibrio con l\'ambiente significherebbe gradienti azzerati, potenziale di membrana a 0 mV, entropia massima: cioè morte.', { p: 1 });
  A('01', 'Omeostasi', 'Il termine «omeostasi» (dal greco hòmoios, «simile») significa letteralmente…', ['mantenersi simile, non identico né fisso', 'mantenersi uguale a un valore fisso', 'tornare all\'equilibrio con l\'ambiente', 'resistere a qualunque cambiamento'], 'I parametri vitali oscillano attorno a un valore di riferimento (set-point) dentro un intervallo fisiologico: sono stabili, non fissi.', { p: 1 });
  A('01', 'Storia', 'La «fissità dell\'ambiente interno» e il termine «omeostasi» sono rispettivamente di…', ['Claude Bernard e Walter Cannon', 'Walter Cannon e Claude Bernard', 'Claude Bernard e Alan Hodgkin', 'Walter Cannon e Ernest Starling'], 'Bernard (fine \'800) formula il principio della costanza del milieu intérieur; Cannon (inizio \'900) conia il termine omeostasi.');
  A('01', 'Anello di controllo', 'In un circuito di controllo a retroazione negativa, il comparatore…', ['confronta il valore misurato con il set-point', 'misura la grandezza controllata e la trasmette', 'esegue la correzione dell\'errore osservato', 'genera la perturbazione sulla grandezza'], 'Il sensore misura, il comparatore sottrae (errore = valore ideale − valore reale) e produce un segnale d\'errore, l\'effettore corregge.', { p: 1 });
  A('01', 'Anello di controllo', 'Nel brivido da freddo, quale struttura ha il ruolo di effettore?', ['Il muscolo scheletrico', 'I termocettori della cute', 'L\'ipotalamo anteriore', 'Il set-point di circa 37 °C'], 'I termocettori sono i sensori, l\'ipotalamo il comparatore (calcola l\'errore rispetto al set-point), il muscolo scheletrico l\'effettore: contrazioni asincrone che producono calore.', { p: 1 });
  A('01', 'Anello di controllo', 'Nel termostato di un\'abitazione, la centralina dove si imposta la temperatura desiderata corrisponde…', ['al comparatore con il suo set-point', 'al sensore della temperatura', 'all\'effettore, cioè alla caldaia', 'alla grandezza controllata'], 'Il sensore misura la temperatura della stanza e la invia alla centralina (comparatore); questa accende o spegne la caldaia (effettore).', { p: 1 });
  A('01', 'Retroazione negativa', 'In un sistema a retroazione negativa proporzionale con guadagno K, l\'errore residuo causato da un disturbo d è…', ['d/(1+K): cala con K ma non si annulla', 'zero, qualunque sia il valore di K', 'd·K: cresce all\'aumentare di K', 'indipendente dal guadagno K'], 'La retroazione negativa riduce l\'errore ma non lo azzera; con K molto grande l\'errore tende a zero, ma un ritardo nell\'anello può rendere il sistema oscillante.');
  A('01', 'Retroazione positiva', 'Rispetto alla retroazione negativa, quella positiva…', ['amplifica la variazione e allontana il parametro dal set-point', 'riporta il parametro verso il set-point in modo più rapido', 'è la forma più frequente nei sistemi viventi', 'serve a mantenere stabile il parametro'], 'Il feedback negativo contrasta la perturbazione (stabilità, omeostasi, prevalente); il positivo la rinforza ed è limitato a eventi transitori che devono completarsi rapidamente.', { p: 1 });
  A('01', 'Retroazione positiva', 'Quale esempio di retroazione positiva ha usato la prof?', ['Il parto, con l\'ossitocina che contrae l\'utero', 'La glicemia regolata da insulina e glucagone', 'La termoregolazione con brivido e sudorazione', 'La regolazione degli ormoni tiroidei'], 'La dilatazione della cervice, rilevata da meccanocettori, fa rilasciare ossitocina dalla neuroipofisi; questa contrae l\'utero e ne aumenta i recettori, e le contrazioni dilatano ancora di più la cervice. Il ciclo si interrompe quando il feto è espulso.', { p: 1 });
  A('01', 'Retroazione positiva', 'Nel parto, l\'ossitocina oltre a contrarre l\'utero…', ['aumenta i recettori per l\'ossitocina sulle cellule muscolari lisce', 'inibisce il rilascio di ossitocina dall\'ipotalamo stesso', 'riduce lo stiramento meccanico della cervice uterina', 'aumenta il rilascio di ADH dalla neuroipofisi'], 'L\'aumento dei recettori rende l\'utero più sensibile: contrazioni più forti e frequenti, più dilatazione, più ossitocina. È un circolo auto-rigenerante.', { p: 1 });
  A('01', 'Termini corretti', 'Mammiferi e uccelli sono definiti in fisiologia…', ['omeotermi, a temperatura interna costante', 'eterotermi, a temperatura interna variabile', 'animali «a sangue caldo» in senso proprio', 'omeotermi solo durante l\'attività fisica'], 'La suddivisione ottocentesca «sangue caldo/freddo» è superata. Rettili, anfibi, pesci e invertebrati sono eterotermi (regolano la temperatura col comportamento, per esempio al sole).', { p: 1 });
  A('01', 'Termini corretti', 'In fisiologia, ciò che si scambia con l\'ambiente è…', ['il calore, cioè energia termica', 'la temperatura dei corpi', 'il freddo come entità fisica', 'l\'entropia negativa dell\'ambiente'], 'La temperatura è una grandezza di stato; si scambia calore. Anche «stabilità» è preferibile a «fissità assoluta».', { p: 1 });
  A('01', 'Termoregolazione', 'La sudorazione raffredda il corpo perché…', ['l\'evaporazione richiede calore latente, sottratto alla cute', 'il sudore liquido appena secreto è più freddo della pelle', 'i sali disciolti nel sudore assorbono il calore dalla cute', 'il sudore riduce il metabolismo basale dei tessuti cutanei'], 'Non è il sudore liquido a raffreddare, ma il passaggio da liquido a vapore (alto calore latente di evaporazione dell\'acqua, circa 2440 J/g).', { p: 1 });
  A('01', 'Termoregolazione', 'In un ambiente molto caldo e molto umido il sudore raffredda poco perché…', ['non evapora: la tensione di vapore cute-aria si azzera', 'le ghiandole sudoripare smettono di secernere', 'il sudore secreto diventa fortemente ipertonico', 'la vasodilatazione cutanea si inverte in costrizione'], 'Con aria satura di vapore acqueo il gradiente di tensione di vapore è nullo: il sudore resta liquido e il potere termodisperdente crolla (rischio di colpo di calore).', { p: 1 });
  A('01', 'Termoregolazione', 'La vasodilatazione cutanea favorisce la perdita di calore perché…', ['porta più sangue caldo dal nucleo ai capillari della pelle', 'riduce la produzione di calore dei muscoli scheletrici', 'attiva direttamente la secrezione delle ghiandole sudoripare', 'raffredda il nucleo senza alcuno scambio con l\'esterno'], 'Rilasciando la muscolatura liscia delle arteriole cutanee aumenta la perfusione superficiale e la cessione di calore per irraggiamento e convezione.');
  A('01', 'Termoregolazione', 'Quale affermazione sulla tolleranza termica dell\'uomo è corretta?', ['Tollera molto peggio un aumento di pochi gradi che un raffreddamento', 'Tollera meglio un aumento di pochi gradi che un raffreddamento', 'Tollera allo stesso modo variazioni di 5 °C in più o in meno', 'Non tollera alcuna variazione della temperatura centrale'], 'Verso i 41–42 °C si hanno denaturazione di proteine, collasso delle membrane e delle sinapsi; il freddo invece rallenta il metabolismo (ipotermia terapeutica in cardiochirurgia).');
  A('01', 'Acqua corporea', 'Nell\'adulto, la maggior parte dell\'acqua corporea si trova…', ['nel compartimento intracellulare, circa 2/3', 'nel plasma dei vasi sanguigni', 'nel liquido interstiziale tra le cellule', 'nel liquor e nelle cavità specializzate'], 'Circa 2/3 dell\'acqua è intracellulare e 1/3 extracellulare; di questo, circa l\'80% è interstiziale e il 20% plasma.');
  A('01', 'Bilancio idrico', 'Perché la produzione di urina non può essere azzerata?', ['Serve un volume minimo per eliminare i soluti di scarto', 'I reni non possono ridurre l\'acqua che riassorbono', 'L\'urina è l\'unica via di perdita d\'acqua del corpo', 'L\'ADH la mantiene sempre a un volume costante'], 'Serve un volume urinario minimo (circa mezzo litro al giorno) per eliminare i soluti da escretare; la perspiratio insensibilis e il sudore sono altre vie di perdita.', { p: 1 });
  A('01', 'Recettore', 'Il termine «recettore» in fisiologia può indicare…', ['una proteina che lega un ligando o una cellula sensoriale', 'soltanto una proteina di membrana con un sito di legame', 'soltanto una cellula specializzata nel rilevare gli stimoli', 'solo un enzima che trasforma chimicamente il ligando'], 'La prof avverte che confondere i due significati è un errore frequente agli esami: recettore molecolare (proteina) e recettore sensoriale (cellula, per esempio meccanocettore o fotorecettore).', { p: 2 });
  A('01', 'Recettore', 'Un ormone idrofilo come l\'insulina agisce su…', ['un recettore di membrana, perché non attraversa il doppio strato', 'un recettore intracellulare raggiunto attraversando la membrana', 'recettori nucleari che modulano direttamente la trascrizione', 'qualsiasi cellula, perché tutte possiedono il suo recettore'], 'Le molecole idrofiliche non attraversano la tela lipidica e si legano a proteine di membrana; gli ormoni lipofili (per esempio quelli tiroidei) entrano e legano recettori intracellulari. Rispondono solo le cellule con il recettore specifico.', { p: 1 });
  A('01', 'Ormoni tiroidei', 'Quale ormone tiroideo è biologicamente attivo?', ['T3, ricavato dal T4 per deiodinazione', 'T4, che funziona da ormone attivo principale', 'T4 e T3 allo stesso modo, con tre iodi ciascuno', 'il TSH, prodotto direttamente dalla tiroide'], 'T4 (tiroxina, 4 atomi di iodio) è secreto in quantità prevalente ed è un pro-ormone; T3 (3 atomi di iodio) ha la conformazione ottimale per il recettore. Il TSH è prodotto dall\'adenoipofisi.', { p: 1 });
  A('01', 'Ormoni tiroidei', 'Un eccesso di ormoni tiroidei nel sangue…', ['inibisce la secrezione di TRH e di TSH', 'stimola l\'ipofisi a produrre più TSH', 'non ha alcun effetto sull\'ipotalamo', 'aumenta la sintesi ipotalamica di TRH'], 'È un feedback negativo: gli ormoni tiroidei agiscono su ipotalamo (TRH) e adenoipofisi (TSH), spegnendo a cascata l\'asse.');
  A('01', 'Ormoni tiroidei', 'Quale quadro è tipico dell\'ipertiroidismo?', ['Metabolismo accelerato, magrezza, intolleranza al caldo', 'Metabolismo rallentato e tendenza al sovrappeso', 'Intolleranza al freddo e scarsa termogenesi', 'Ritardo mentale grave già alla nascita'], 'Ipotiroidismo: metabolismo rallentato, freddolosi, sovrappeso. Ipertiroidismo: metabolismo accelerato, eccesso di calore, magrezza, esoftalmo. Il deficit congenito di ormoni tiroidei dà il cretinismo.');
  A('01', 'Comunicazione', 'La comunicazione endocrina si distingue da quella elettrica perché…', ['usa il sangue come veicolo e agisce a distanza', 'richiede il contatto sinaptico tra cellule adiacenti', 'agisce su tutte le cellule senza distinzione', 'è la più veloce, perché non usa recettori'], 'Mittente (ghiandola), veicolo (sangue), ricevente (solo le cellule con il recettore specifico). La comunicazione elettrica passa fra cellule contigue nelle sinapsi.');
  A('01', 'Disidratazione', 'Quale percorso descrive la risposta di risparmio d\'acqua nella disidratazione?', ['Sensori osmometrici, ipotalamo, neuroipofisi (ADH), rene', 'Termocettori, ipotalamo, ghiandole sudoripare', 'Sensori osmometrici, ipotalamo, muscolo scheletrico', 'Adenoipofisi, ADH, tiroide'], 'La neuroipofisi (estensione del sistema nervoso, assoni di neuroni ipotalamici) libera ADH e ossitocina; l\'ADH fa produrre al rene urina concentrata. Si attiva anche il comportamento della sete.', { p: 1 });

  // ======================================================================= 02 — Termodinamica
  A('02', 'Sistemi', 'Un organismo vivente, dal punto di vista termodinamico, è…', ['un sistema aperto, che scambia materia ed energia', 'un sistema chiuso, che scambia solo energia', 'un sistema isolato, senza scambi con l\'esterno', 'un sistema in equilibrio con l\'ambiente'], 'L\'unico vero sistema isolato noto è l\'Universo.', { p: 1 });
  A('02', 'Primo principio', 'Un sistema assorbe il calore Q e compie il lavoro L. La variazione della sua energia interna è…', ['ΔU = Q − L', 'ΔU = Q + L', 'ΔU = L − Q', 'ΔU = Q · L'], 'È il primo principio: l\'energia non si crea né si distrugge, si trasforma. In un sistema isolato ΔU = 0.');
  A('02', 'Secondo principio', 'In un sistema isolato, i processi spontanei procedono verso…', ['un aumento dell\'entropia, cioè del disordine', 'una diminuzione dell\'entropia del sistema', 'un aumento dell\'energia libera disponibile', 'un aumento dell\'ordine molecolare'], 'La cameretta lasciata a se stessa passa dall\'ordine al disordine, il castello di carte crolla e non si ricostruisce da solo.', { p: 1 });
  A('02', 'Entropia', 'Per un sistema che scambia il calore Q alla temperatura T, la variazione di entropia è…', ['ΔS = Q/T', 'ΔS = Q·T', 'ΔS = T/Q', 'ΔS = Q − T'], 'Da Q = T·ΔS: l\'entropia è legata all\'agitazione termica e al calore.');
  A('02', 'Rendimento', 'Perché nessuna trasformazione energetica reale ha rendimento del 100%?', ['Una parte dell\'energia si disperde come calore', 'Una parte dell\'energia viene distrutta', 'Il primo principio lo vieta esplicitamente', 'L\'entropia del sistema deve diminuire'], 'Il secondo principio impone una quota dissipata come calore: il ghepardo che corre scalda, il motore poco efficiente consuma più carburante.', { p: 1 });
  A('02', 'Energia libera', 'Nella relazione ΔU = ΔG + TΔS, il termine TΔS rappresenta…', ['l\'energia legata all\'entropia, non usabile per lavoro', 'l\'energia utile per compiere il lavoro', 'l\'energia potenziale accumulata nel sistema', 'il lavoro realmente compiuto dal sistema'], 'ΔG è l\'energia libera, cioè la parte realmente disponibile per compiere lavoro. In forma rigorosa a T e P costanti: ΔG = ΔH − TΔS.', { p: 1 });
  A('02', 'Energia libera', 'Per l\'Universo (ΔU = 0) vale ΔG = −TΔS. Se l\'entropia dell\'Universo aumenta, l\'energia libera…', ['diminuisce', 'aumenta', 'resta costante', 'dipende dalla temperatura'], 'Da 0 = ΔG + TΔS: a un aumento di entropia corrisponde una diminuzione di energia libera, cioè un processo spontaneo.', { p: 1 });
  A('02', 'Vita e secondo principio', 'Rispetto al secondo principio, gli organismi viventi, pur così ordinati…', ['lo rispettano, spendendo energia e aumentando l\'entropia esterna', 'lo violano, perché riducono l\'entropia al loro interno', 'lo rispettano solo perché restano in equilibrio con l\'ambiente', 'non ne sono soggetti, dato che sono sistemi aperti e non isolati'], 'Il vivente riversa calore e disordine all\'esterno: l\'entropia complessiva dell\'Universo aumenta.', { p: 1 });
  A('02', 'Equilibrio e morte', 'Un mammifero immerso nel freddo, lasciato a sé, tenderebbe spontaneamente…', ['a cedere calore fino all\'equilibrio con l\'esterno', 'a conservare la temperatura grazie al secondo principio', 'ad aumentare la propria temperatura corporea', 'a diminuire l\'entropia dell\'ambiente circostante'], 'Come la bottiglia fredda che in estate si scalda spontaneamente. L\'organismo spende attivamente energia metabolica per opporsi a questo equilibrio (equilibrio termodinamico = morte).', { p: 1 });
  A('02', 'Trasduzione', 'In bioenergetica, la «trasduzione» indica…', ['la conversione di una forma di energia in un\'altra', 'il passaggio di un segnale attraverso una sinapsi', 'la sintesi di ATP a partire da ADP e Pi', 'la perdita di energia sotto forma di calore'], 'Il muscolo scheletrico, per esempio, converte l\'energia chimica dell\'ATP in energia meccanica (e calore): gli organismi sono «motori biologici».', { p: 1 });
  A('02', 'Brivido', 'Perché nel brivido quasi tutta l\'energia dell\'ATP idrolizzato diventa calore?', ['Le contrazioni asincrone non producono lavoro utile', 'Nel brivido l\'ATP non viene affatto consumato', 'Il muscolo ha un rendimento del 100% nel brivido', 'Il calore nasce solo nel tessuto adiposo bruno'], 'Nel muscolo striato solo circa il 20–25% dell\'energia libera dell\'ATP diventa lavoro; senza movimento macroscopico il resto, cioè praticamente tutto, scalda il sangue.', { p: 1 });
  A('02', 'Origine dell\'energia', 'L\'energia che le cellule usano per dividersi, pensare e correre deriva in ultima analisi…', ['dalle reazioni nucleari del Sole, catturate dagli autotrofi', 'dall\'energia che il metabolismo crea dal nulla nei mitocondri', 'dalla scissione delle molecole d\'acqua nei mitocondri', 'dall\'aumento di entropia dell\'ambiente circostante'], 'L\'energia non si crea: passa attraverso i livelli trofici.', { p: 1 });

  // ======================================================================= 03 — ATP e accoppiamento
  A('03', 'Accoppiamento', 'Una reazione endoergonica (ΔG > 0) in una cellula può avvenire se…', ['è accoppiata a una esoergonica con ΔG più negativo', 'è accoppiata a una con ΔG uguale ma di segno opposto', 'la temperatura della cellula viene aumentata', 'è catalizzata da un enzima specifico, anche da solo'], 'Deve essere |ΔG esoergonica| > |ΔG endoergonica|, così che il ΔG netto sia negativo. Metafora del sasso: serve chi lo porti in salita con più forza del suo peso. Un enzima abbassa la barriera, non cambia il ΔG.', { p: 1 });
  A('03', 'Composti XP', 'Nella sintesi A + B → AB (ΔG > 0), l\'intermedio fosforilato A–P…', ['è più energetico di A e reagisce spontaneamente con B', 'è meno energetico di A e reagisce con B perché stabile', 'reagisce con B senza avere ricevuto il fosfato', 'serve solo a rendere A più solubile in acqua'], 'XP cede il fosfato ad A (energizzazione); A–P reagisce con B e forma AB, rilasciando Pi. È ciò che accade nella biosintesi del glicogeno, che usa monomeri di glucosio fosforilati.', { p: 1 });
  A('03', 'ATP', 'Perché l\'idrolisi dell\'ATP in ADP + Pi libera energia?', ['I prodotti sono più stabili, con cariche stabilizzate per risonanza', 'L\'ATP è instabile perché non possiede alcuna carica elettrica netta', 'L\'energia è accumulata nel legame che resta fra ADP e Pi', 'L\'acqua coinvolta nella reazione cede energia ai prodotti'], 'ΔG < 0 e ΔS > 0: la reazione è spontanea ed esoergonica. È come passare dal castello di carte alle carte a terra.', { p: 1 });
  A('03', 'ATP', 'Perché nella cellula l\'idrolisi dell\'ATP libera più energia dei −30,5 kJ/mol standard?', ['Il rapporto [ADP][Pi]/[ATP] è molto basso', 'La temperatura cellulare è di 37 °C', 'L\'ATP è legato al Mg²⁺ nel citosol', 'Il ΔG°′ cambia quando entra nella cellula'], 'ΔG = ΔG°′ + RT ln([ADP][Pi]/[ATP]): con ATP abbondante il logaritmo è molto negativo.');
  A('03', 'ATP', 'La sintesi di ATP da ADP e Pi…', ['è endoergonica e richiede energia dal catabolismo o dalla luce', 'è esoergonica e avviene spontaneamente nella cellula', 'avviene soltanto all\'interno dei mitocondri', 'non richiede energia perché l\'ATP è instabile'], 'Autotrofi fotosintetici: energia radiante. Eterotrofi (animali): ossidazione dei substrati alimentari.', { p: 1 });
  A('03', 'Lavoro biologico', 'Quale processo NON è alimentato direttamente dall\'idrolisi dell\'ATP?', ['La diffusione semplice dell\'O₂ attraverso la membrana', 'La contrazione dei miofilamenti nel muscolo', 'Il trasporto attivo contro gradiente di un soluto', 'La biosintesi di macromolecole a partire da monomeri'], 'La diffusione semplice è passiva e segue il gradiente; i lavori biologici sono processi endoergonici sostenuti dall\'ATP.');
  A('03', 'Catabolismo', 'Rispetto alla glicolisi anaerobica, l\'ossidazione completa del glucosio nei mitocondri…', ['rende molto più ATP, arrivando a CO₂ e H₂O', 'rende meno ATP ma in modo più rapido', 'non produce calore metabolico', 'avviene in assenza di ossigeno'], 'In anaerobiosi il glucosio è ossidato solo parzialmente (piruvato o lattato).');
  A('03', 'Respirazione', 'Perché la respirazione cellulare non produce fiamma, a differenza della combustione del glucosio in provetta?', ['L\'ossidazione è frazionata in tappe e l\'energia è catturata in ATP', 'Avviene a bassa temperatura e senza usare ossigeno molecolare', 'Libera una quantità minore di energia totale dal glucosio', 'Non è una reazione di ossidoriduzione ma di idrolisi'], 'Il ΔG totale è lo stesso; nella cellula viene rilasciato gradualmente e in parte trattenuto nei legami dell\'ATP, il resto è calore metabolico.', { p: 1 });
  A('03', 'Nutrienti', 'Quale gruppo di principi alimentari ha prevalentemente funzione plastica (costruzione e riparazione dei tessuti)?', ['Le proteine', 'I carboidrati', 'I lipidi', 'L\'acqua'], 'Energetici: carboidrati e lipidi. Regolatori e protettivi: vitamine e sali. L\'acqua è il solvente vitale e non fornisce calorie.', { p: 1 });

  A('03', 'Lavoro meccanico', 'Nel lavoro meccanico della cellula, l\'energia dell\'ATP viene usata per…', ['fosforilare proteine motrici che spostano altre proteine', 'spostare ioni contro il loro gradiente elettrochimico', 'sintetizzare nuove molecole complesse da monomeri', 'dissipare calore e mantenere la temperatura'], 'Le tre forme di lavoro biologico sono meccanico (proteine motrici: nel muscolo actina e miosina, nel neurone chinesina e dineina sui microtubuli), di trasporto (pompe) e chimico (biosintesi).');

  // ======================================================================= 04 — Membrana: lipidi
  A('04', 'Fosfolipidi', 'Un fosfolipide è definito «anfipatico» perché…', ['ha una testa idrofila e code idrofobiche', 'si scioglie sia in acqua sia in solventi organici', 'è una molecola priva di qualsiasi carica', 'è formato soltanto da acidi grassi'], 'La prof usa l\'immagine del Dr. Jekyll e Mr. Hyde. Glicerolo, due acidi grassi, fosfato e una base organica (per esempio la colina).', { p: 1 });
  A('04', 'Autoassemblaggio', 'In ambiente acquoso, i fosfolipidi a geometria cilindrica formano spontaneamente…', ['un doppio strato (bilayer)', 'micelle sferiche di fosfolipidi', 'un monostrato rigido e compatto', 'cristalli lipidici stabili'], 'I fosfolipidi conici formano micelle; quelli cilindrici doppi strati. L\'assemblaggio è spontaneo perché è la configurazione a minore energia libera.', { p: 1 });
  A('04', 'Fluidità', 'Per mantenere la fluidità di membrana al calare della temperatura, i poichilotermi…', ['aumentano gli acidi grassi insaturi con doppi legami cis', 'aumentano gli acidi grassi saturi a catena lunga', 'eliminano il colesterolo dalla membrana', 'riducono il numero delle proteine di membrana'], 'I doppi legami cis creano pieghe che impediscono l\'impacchettamento rigido: la membrana non «congela» come il burro in frigorifero.', { p: 1 });
  A('04', 'Colesterolo', 'Nelle cellule animali il colesterolo è detto «jolly» perché…', ['modula la fluidità in entrambi i sensi', 'rende la membrana sempre più rigida', 'rende la membrana sempre più fluida', 'forma i pori dei canali ionici'], 'Impedisce sia l\'eccessivo impacchettamento sia l\'eccessiva fluidificazione: è un modulatore bidirezionale di fluidità e stabilità meccanica.', { p: 1 });
  A('04', 'Asimmetria', 'Quale caratteristica distingue i due foglietti del doppio strato plasmatico?', ['I glucidi sono solo sul foglietto esterno', 'I glucidi sono solo sul foglietto interno', 'I lipidi sono identici nei due foglietti', 'Le proteine sono solo sul foglietto esterno'], 'Il glicocalice è esclusivamente extracellulare. Nel foglietto interno prevale la fosfatidilserina (carica netta negativa), nell\'esterno la fosfatidilcolina: una polarità elettrica primordiale su cui si innesta il potenziale di membrana.', { p: 1 });
  A('04', 'Asimmetria', 'La fosfatidilserina si trova prevalentemente…', ['nel foglietto interno, con carica netta negativa', 'nel foglietto esterno, con carica netta negativa', 'nel foglietto interno, ed è elettricamente neutra', 'nei due foglietti in quantità uguali'], 'L\'asimmetria lipidica contribuisce alla separazione di cariche: negativa dentro, positiva fuori.', { p: 1 });
  A('04', 'Dinamica', 'Tra i movimenti dei fosfolipidi nel doppio strato, il più lento e raro è…', ['il flip-flop da un foglietto all\'altro', 'la diffusione laterale nello stesso foglietto', 'la rotazione attorno al proprio asse', 'la flessione delle catene aciliche'], 'Il flip-flop richiede il passaggio della testa polare attraverso il core idrofobico e di solito è catalizzato da enzimi.');
  A('04', 'Sistema delle membrane', 'Le MAMs (mitochondria-associated membranes) sono…', ['siti di contatto reticolo-mitocondri per lo scambio di Ca²⁺', 'canali per il Ca²⁺ nella membrana plasmatica della cellula', 'proteine ancorate al glicocalice sul lato extracellulare', 'zone di membrana plasmatica prive di fosfolipidi e colesterolo'], 'Il Ca²⁺ è alto fuori dalla cellula e negli organelli, bassissimo nel citosol libero.', { p: 1 });
  A('04', 'Struttura', 'Il doppio «binario» della membrana (due linee scure con zona chiara) si osserva…', ['solo al microscopio elettronico a trasmissione', 'al microscopio ottico a 1000 ingrandimenti', 'soltanto con la microscopia a fluorescenza', 'soltanto nelle cellule vegetali con parete'], 'Al microscopio ottico si distingue solo il contorno cellulare.', { p: 1 });
  A('04', 'Mosaico fluido', 'Rispetto alle cellule vegetali e ai funghi, le cellule animali…', ['non hanno parete, quindi sono più esposte a shock osmotici', 'non hanno una membrana plasmatica propria ma solo la parete', 'hanno una membrana priva di proteine integrali e periferiche', 'hanno una parete più sottile ma comunque presente intorno'], 'La parete rigida protegge dagli shock osmotici; la membrana plasmatica c\'è in tutte le cellule.', { p: 1 });

  // ======================================================================= 05 — Membrana: proteine e glicocalice
  A('05', 'Proteine di membrana', 'Le proteine integrali, rispetto a quelle periferiche, si estraggono dal doppio strato…', ['solo con detergenti forti, per le interazioni idrofobiche', 'con detergenti blandi o variando la forza ionica', 'senza alcun trattamento, per semplice lavaggio', 'solo scaldando il campione a 100 °C'], 'Le periferiche e quelle ancorate con lipidi si dissociano con trattamenti blandi.', { p: 1 });
  A('05', 'Proteine di membrana', 'I segmenti transmembrana ad α-elica sono formati soprattutto da amminoacidi…', ['apolari, che interagiscono con le code dei fosfolipidi', 'carichi positivamente, che attirano le teste polari', 'carichi negativamente, che attirano gli ioni Na⁺', 'polari e idrofili, esposti all\'acqua'], 'Le anse e i domini extra- e intracellulari, immersi in ambiente acquoso, contengono amminoacidi polari o carichi.', { p: 1 });
  A('05', 'Proteine di membrana', 'In una proteina transmembrana multipasso, all\'aumentare del numero di segmenti transmembrana…', ['aumenta l\'idrofobicità complessiva della proteina', 'diminuisce l\'idrofobicità complessiva della proteina', 'le anse diventano a loro volta idrofobiche', 'la proteina diventa una proteina periferica'], 'Le eliche sono unite da anse intra- ed extracellulari; nei libri le proteine sono disegnate «distese» ma nello spazio si ripiegano in strutture terziarie e quaternarie.');
  A('05', 'Recettori', 'Il recettore dell\'insulina è…', ['tirosin-chinasico a singolo passo, con dimerizzazione', 'a 7 segmenti accoppiato a una proteina G', 'un canale ionico a 5 subunità', 'un recettore intracellulare di tipo nucleare'], 'Il legame induce dimerizzazione e autofosforilazione dei residui di tirosina: cascata di fosforilazioni su enzimi del metabolismo glucidico, con effetto diretto e rapido.', { p: 1 });
  A('05', 'Recettori', 'Il recettore del glucagone, accoppiato a una proteina Gs, porta a…', ['attivazione dell\'adenilato ciclasi, più cAMP e PKA attiva', 'inibizione dell\'adenilato ciclasi e calo del cAMP', 'apertura diretta di un canale ionico', 'autofosforilazione di un dominio chinasico'], 'Le proteine Gi inibiscono invece l\'adenilato ciclasi e riducono il cAMP. La subunità α si separa dal dimero βγ e raggiunge l\'effettore.', { p: 1 });
  A('05', 'Trasporto', 'Il modello di funzionamento di un carrier («schiaccianoci») prevede…', ['legame del soluto e accesso alternato ai due lati', 'un poro acquoso che resta sempre aperto', 'una galleria con una porta sensibile al voltaggio', 'una semplice diffusione attraverso il doppio strato'], 'Il carrier si comporta come un enzima, ma sposta il soluto senza trasformarlo chimicamente.', { p: 1 });
  A('05', 'Trasporto', 'Secondo la fisiologia moderna, passando in un canale ionico lo ione…', ['interagisce attivamente con le pareti del poro', 'non interagisce in alcun modo con il canale', 'si lega a un sito e viene trasformato', 'attraversa il doppio strato lipidico'], 'Il «vecchio dogma» riteneva che nei canali non ci fosse interazione: ora si sa che dimensioni del poro e cariche delle pareti determinano la selettività.', { p: 1 });
  A('05', 'Proporzioni', 'Quale membrana ha il rapporto lipidi/proteine più alto, ed è un ottimo isolante elettrico?', ['La mielina', 'La membrana mitocondriale interna', 'La membrana del reticolo sarcoplasmatico', 'La membrana dell\'eritrocita'], 'La mielina è quasi priva di proteine; la membrana mitocondriale interna è la più ricca di proteine (catena respiratoria e ATP sintasi), l\'eritrocita ha circa 50% e 50%.', { p: 1 });
  A('05', 'Ancoraggi', 'Le proteine estrinseche possono ancorarsi in modo reversibile alla membrana tramite…', ['acido miristico o palmitico, gruppi prenilici, ancora GPI', 'domini transmembrana ad α-elica idrofobici', 'legami covalenti con le molecole di colesterolo', 'canali ionici che le trattengono in membrana'], 'L\'ancora funziona come un segnale: si aggiunge o si rimuove, e i legami sono più deboli delle interazioni idrofobiche delle proteine integrali.');
  A('05', 'Glicocalice', 'Quale funzione NON è attribuita al glicocalice?', ['Formare i pori dei canali ionici', 'Riconoscere il self e il non-self (MHC, CD)', 'Mediare l\'adesione cellula-cellula e cellula-matrice', 'Proteggere meccanicamente e chimicamente la membrana'], 'Il glicocalice è un mantello di catene glucidiche su glicoproteine e glicolipidi del versante extracellulare.');
  A('05', 'Tecniche', 'Nella SDS-PAGE, le proteine migrano nel gel in funzione…', ['del solo peso molecolare, perché l\'SDS uniforma la carica', 'della carica nativa, che resta quella originale', 'della conformazione nativa, che l\'SDS conserva', 'della solubilità in acqua della proteina'], 'L\'SDS denatura le proteine e le riveste di cariche negative. La BN-PAGE (Blue Native) è invece in condizioni native: conserva conformazione e attività enzimatica, ed è la tecnica d\'elezione per i complessi di membrana come la catena respiratoria.', { p: 1 });
  A('05', 'Canali', 'Il canale delle giunzioni comunicanti (gap junction) è formato da…', ['due connessoni affacciati, di 6 connessine ciascuno', 'un unico connessone formato da 4 subunità identiche', 'due emicanali formati da 5 subunità ciascuno', 'una singola proteina a 7 segmenti transmembrana'], 'I canali voltaggio-dipendenti hanno 4 subunità o domini; i recettori-canale (chemio-dipendenti) 5 subunità; le connessine sono 6 per connessone, 12 in tutto.', { p: 1 });
  A('05', 'Mobilità', 'L\'esperimento di Frye ed Edidin dimostra che…', ['le proteine di membrana si muovono per diffusione laterale', 'le proteine di membrana sono fisse nel doppio strato', 'i fosfolipidi non si muovono nel piano della membrana', 'le membrane di cellule diverse non possono fondersi'], 'Dopo la fusione indotta da virus fra cellule di uomo e topo, le proteine marcate delle due specie si mescolano lungo l\'unica membrana. Le proteine si muovono più lentamente dei fosfolipidi e in alcune zone formano zattere lipidiche (lipid rafts).', { p: 1 });
  A('05', 'Ligandi', 'La nicotina agisce sul recettore colinergico nicotinico come…', ['agonista esogeno che mima l\'acetilcolina', 'antagonista endogeno dell\'acetilcolina', 'modulatore che si lega a un sito diverso', 'inibitore dell\'acetilcolinesterasi'], 'I ligandi endogeni sono prodotti dall\'organismo (acetilcolina), gli esogeni vengono dall\'esterno (farmaci, tossine, sostanze vegetali).', { p: 1 });

  // ======================================================================= 06 — Flussi e legge di Teorell
  A('06', 'Teorell', 'L\'equazione di Teorell, F = K·X, afferma che il flusso di una sostanza è…', ['direttamente proporzionale alla forza spingente', 'inversamente proporzionale alla forza spingente', 'proporzionale al quadrato della forza spingente', 'indipendente dalla forza spingente applicata'], 'Il flusso F è dato da una costante K (che dipende dal sistema) per la forza spingente X = −dμ/dx. Si trascurano attrito e urti fra le particelle.', { p: 1 });
  A('06', 'Teorell', 'La prima legge di Ohm, I = ΔV/R, è un caso particolare dell\'equazione di Teorell in cui la conduttanza 1/R corrisponde…', ['alla costante di proporzionalità K', 'alla forza spingente X', 'al flusso F di particelle', 'alla differenza di potenziale ΔV'], 'Corrente I = flusso F; conduttanza 1/R = costante K; differenza di potenziale ΔV = forza spingente X.', { p: 1 });
  A('06', 'Tipi di flusso', 'Nel flusso di massa, la forza spingente è…', ['la differenza di pressione idraulica ΔP', 'la differenza di concentrazione ΔC', 'la differenza di potenziale elettrico ΔV', 'la differenza di temperatura ΔT'], 'Nel flusso di massa si muove l\'intera soluzione (soluto e solvente insieme); F_m = K_m·ΔP, con K_m che racchiude viscosità e geometria del condotto.', { p: 1 });
  A('06', 'Tipi di flusso', 'Se si sposta soltanto il soluto sotto l\'azione di un gradiente di concentrazione, si parla di…', ['diffusione', 'flusso di massa', 'osmosi', 'migrazione elettrica'], 'Se si sposta solo il solvente (acqua) attraverso una barriera si parla di osmosi; per particelle cariche in un campo elettrico, di elettroforesi (elettrodiffusione).', { p: 1 });
  A('06', 'Flusso di massa', 'Se aumenta la viscosità del sangue o un vaso si ostruisce (trombo), il coefficiente K_m…', ['si riduce, e a parità di ΔP il flusso diminuisce', 'aumenta, e a parità di ΔP il flusso aumenta', 'non cambia, ma cambia la forza spingente ΔP', 'diventa negativo, e il flusso si inverte'], 'K_m racchiude viscosità del fluido e geometria dei vasi: più viscosità o più ostruzione, meno flusso.', { p: 1 });
  A('06', 'Equilibrio dinamico', 'Quando due compartimenti collegati raggiungono l\'equilibrio diffusivo, il flusso netto è nullo perché…', ['i flussi unidirezionali nei due versi sono uguali', 'le particelle hanno smesso di muoversi', 'il soluto è stato completamente consumato', 'il flusso di ritorno è diventato superiore'], 'F_1→2 = F_2→1 ⇒ F_N = 0: le particelle continuano a muoversi, ma i due flussi si controbilanciano (equilibrio dinamico).', { p: 1 });
  A('06', 'Diffusione nel tempo', 'In due compartimenti comunicanti, con soluto inizialmente solo in 1, nel tempo…', ['C₁ cala e C₂ cresce, entrambe verso lo stesso valore finale', 'C₁ cala fino a zero mentre C₂ resta costante', 'C₁ e C₂ crescono insieme fino a un massimo', 'C₁ resta costante mentre C₂ cresce fino a C₁'], 'ΔC tende a zero in modo asintotico: all\'equilibrio C₁ = C₂ = C_f e il flusso netto è nullo. La prof ha detto che questo grafico può essere richiesto («soddisfatti o rimborsati?»).', { p: 2 });
  A('06', 'Seconda legge di Fick', 'Il tempo che una particella impiega a diffondere cresce con…', ['il quadrato della distanza da percorrere (t ∝ x²)', 'la distanza da percorrere in modo lineare', 'la radice quadrata della distanza', 'l\'inverso del quadrato della distanza'], 'Su scala subcellulare (nm) la diffusione è rapidissima; su distanze macroscopiche diventa lentissima. La prof ha detto che questa domanda nel primo test «c\'è sicuramente».', { p: 2 });
  A('06', 'Seconda legge di Fick', 'Perché gli animali grandi non portano l\'ossigeno ai tessuti per semplice diffusione?', ['Su grandi distanze la diffusione è troppo lenta e serve un flusso di massa', 'L\'ossigeno non è solubile nei liquidi corporei', 'Il gradiente di O₂ tra polmone e tessuti è nullo', 'La diffusione è un processo attivo che consuma troppo ATP'], 'Il tempo cresce col quadrato della distanza: serve la circolazione sanguigna (flusso di massa) con l\'emoglobina.', { p: 1 });
  A('06', 'Termodinamica', 'La diffusione spontanea del saccarosio in acqua è un processo con…', ['ΔG < 0, perché lo stato finale è più stabile', 'ΔG > 0, perché richiede energia dall\'esterno', 'ΔG = 0 fin dall\'inizio del processo', 'ΔS < 0, perché aumenta l\'ordine del sistema'], 'Lo stato iniziale (goccia concentrata) è ordinato e instabile; il sistema evolve verso il massimo disordine liberando energia di solvatazione.');
  A('06', 'Elettrodiffusione', 'Nell\'equazione dell\'elettrodiffusione, per una particella neutra (z = 0) il flusso si riduce…', ['alla sola prima legge di Fick', 'alla sola migrazione in campo elettrico', 'a zero, perché non può muoversi', 'alla legge di Ohm'], 'Il termine elettrico (z·K_e)·ΔV si annulla. Se invece ΔC = 0 resta soltanto la migrazione elettrica.', { p: 1 });
  A('06', 'Elettroforesi', 'In una soluzione di KCl tra due piastre collegate a una batteria, i cationi K⁺ migrano verso…', ['il catodo (polo negativo)', 'l\'anodo (polo positivo)', 'il polo con la concentrazione maggiore', 'nessuno dei due, perché la soluzione è neutra'], 'I cationi vanno al catodo, gli anioni (Cl⁻) all\'anodo; la corrente totale è la somma algebrica delle correnti ioniche.', { p: 1 });
  A('06', 'Circolazione', 'Nella grande circolazione, la forza spingente del flusso sanguigno è…', ['la differenza di pressione tra aorta e atrio destro', 'la differenza di concentrazione di O₂ tra arterie e vene', 'la differenza di temperatura tra nucleo e cute', 'il potenziale elettrico fra ventricolo e atrio'], 'È un flusso di massa: F = K_m·ΔP. Con l\'età i vasi perdono elasticità (compliance) e il cuore deve generare più ΔP.');

  // ======================================================================= 07 — Permeabilità e osmosi
  A('07', 'Coefficiente P', 'Il coefficiente di permeabilità P, definito da F = P·ΔC, è…', ['un indice della facilità con cui una sostanza attraversa la membrana', 'una costante uguale per tutte le sostanze e le membrane', 'la velocità massima raggiungibile dal trasporto', 'la differenza di concentrazione ai due lati'], 'Si misura come P = F/ΔC e riassume particella (dimensioni, lipofilia), membrana (composizione, spessore) e fattori ambientali (temperatura). Più P è basso, più la sostanza attraversa lentamente.', { p: 1 });
  A('07', 'Coefficiente P', 'Per una sostanza liposolubile che attraversa la tela fosfolipidica, la permeabilità dipende soprattutto…', ['dal coefficiente di ripartizione olio/acqua β', 'dal diametro della molecola', 'dalla carica elettrica netta della molecola', 'dalla presenza di un trasportatore specifico'], 'Per le sostanze lipofile la permeabilità non dipende dalle dimensioni: P ∝ β·D_m. Più è alta la lipofilia (β > 1), più è alto P.', { p: 1 });
  A('07', 'Coefficiente β', 'Il coefficiente di ripartizione olio/acqua β è…', ['il rapporto tra la concentrazione nell\'olio e nell\'acqua', 'il rapporto tra la concentrazione nell\'acqua e nell\'olio', 'la differenza tra le due concentrazioni', 'il prodotto delle due concentrazioni'], 'Una sostanza lipofila ha β > 1: tende a sciogliersi nella fase lipidica.', { p: 1 });
  A('07', 'Ioni e dimensioni', 'Per gli ioni, a differenza delle sostanze liposolubili, la permeabilità…', ['dipende dal diametro e si annulla sopra circa 8 Å', 'non dipende dal diametro della particella', 'aumenta all\'aumentare del diametro dello ione', 'dipende solo dalla temperatura della soluzione'], 'È il «modello del setaccio»: la membrana si comporta come un setaccio con pori di dimensioni finite. Ha portato i biofisici a ipotizzare i canali prima che fossero scoperti.', { p: 1 });
  A('07', 'Vie di permeazione', 'Glucosio e amminoacidi, polari e troppo grandi per i pori ionici, attraversano la membrana…', ['tramite carrier, con cinetica di tipo Michaelis-Menten', 'sciogliendosi direttamente nella tela fosfolipidica', 'attraverso i canali ionici selettivi per il sodio', 'solo per diffusione libera, ma lentamente'], 'Le molecole troppo grandi per i canali e prive di carrier specifici non passano affatto (P = 0).', { p: 1 });
  A('07', 'Trabocchetto', 'La tela fosfolipidica è impermeabile al glucosio. La membrana plasmatica lo è?', ['No, perché contiene trasportatori specifici per il glucosio', 'Sì, perché è formata da una tela fosfolipidica', 'Sì, perché il glucosio è una molecola troppo grande', 'No, perché il glucosio è liposolubile'], 'La prof distingue la «tela» (doppio strato puro) dalla membrana biologica (tela + canali e carrier). «La tela è impermeabile al glucosio?» è Vero; «la membrana plasmatica è impermeabile al glucosio?» è Falso.', { p: 2 });
  A('07', 'Trabocchetto', 'Quale gruppo di sostanze attraversa liberamente il doppio strato lipidico puro?', ['O₂, CO₂, etanolo, ormoni steroidei', 'Na⁺, K⁺, Cl⁻ e Ca²⁺', 'Glucosio, amminoacidi e proteine', 'Tutte le molecole polari, indipendentemente dalle dimensioni'], 'Passano le sostanze lipofile, i piccoli gas apolari e le piccole molecole polari non cariche (acqua, etanolo). Ioni e grandi molecole polari rimbalzano contro il doppio strato.', { p: 1 });
  A('07', 'Acqua', 'L\'acqua attraverso la sola tela fosfolipidica…', ['passa per diffusione semplice, ma con bassa permeabilità', 'non può passare, perché è una molecola polare', 'passa rapidamente, grazie alle sue piccole dimensioni', 'passa solo con un trasportatore attivo'], 'Con le acquaporine il flusso osmotico diventa rapido ed efficiente (fino a 100 volte più veloce).', { p: 1 });
  A('07', 'Osmosi', 'Dal punto di vista fisiologico, l\'osmosi è…', ['un flusso passivo di acqua guidato dal gradiente di pressione osmotica', 'un trasporto attivo di acqua che consuma ATP', 'una diffusione di soluto contro il gradiente chimico', 'un flusso di massa guidato dalla pressione idrostatica'], 'Nei sistemi biologici non esistono trasporti attivi primari di sola acqua: l\'acqua si sposta sempre passivamente. L\'osmosi è una diffusione, ma del solvente.', { p: 1 });
  A('07', 'Osmosi', 'Tra due soluzioni separate da una membrana permeabile all\'acqua, l\'acqua si sposta…', ['dove la pressione osmotica è più bassa verso dove è più alta', 'dove la pressione osmotica è più alta verso dove è più bassa', 'dal compartimento più grande al più piccolo', 'verso il compartimento a pressione idrostatica più alta'], 'Cioè da dove il soluto è meno concentrato (più acqua libera) a dove lo è di più. Δπ è condizione necessaria ma non sufficiente: la membrana deve essere permeabile all\'acqua.', { p: 1 });
  A('07', 'van\'t Hoff', 'La pressione osmotica π = R·T·C dipende…', ['solo dal numero di particelle osmoticamente attive per volume', 'dalla natura chimica delle particelle di soluto', 'dalla massa molecolare delle particelle di soluto', 'dalla carica elettrica delle particelle di soluto'], 'È una proprietà colligativa: conta il numero di particelle, non la loro qualità. A temperatura costante π varia solo con C.', { p: 1 });
  A('07', 'Osmolarità', 'Una soluzione 150 mM di NaCl ha un\'osmolarità di circa…', ['300 mOsm, valore del plasma umano', '150 mOsm, uguale alla molarità', '75 mOsm, perché il sale si dissocia', '600 mOsm, per l\'idratazione degli ioni'], 'NaCl si dissocia in 2 particelle (Na⁺ e Cl⁻): è la «soluzione fisiologica», isotonica con i liquidi corporei. Per CaCl₂ 150 mM: 3 particelle, 450 mOsm.', { p: 1 });
  A('07', 'Coefficiente σ', 'Il coefficiente di riflessione σ = 1 indica che…', ['la membrana è impermeabile al soluto: massimo effetto osmotico', 'la membrana è molto permeabile al soluto: nessun effetto', 'la pressione osmotica reale è la metà di quella teorica', 'il soluto e l\'acqua attraversano la membrana ugualmente'], 'Con σ = 0 il soluto passa liberamente e annulla il suo gradiente: la pressione osmotica reale è nulla. Δπ_reale = σ·Δπ_teorico (van\'t Hoff).', { p: 1 });
  A('07', 'Coefficiente σ', 'Se un soluto è molto più permeabile dell\'acqua, il flusso osmotico…', ['non avviene, perché il soluto annulla ΔC prima che l\'acqua si muova', 'è massimo, perché il soluto richiama molta acqua', 'avviene in senso opposto a quello atteso', 'avviene normalmente, perché σ non conta'], 'Il soluto si distribuisce all\'equilibrio e il Δπ teorico si annulla prima che l\'acqua possa muoversi. Per questo isosmotico non significa isotonico (per esempio l\'urea).', { p: 1 });
  A('07', 'Flusso d\'acqua', 'Dalla relazione J_acqua = P_acqua·ΔC_soluto discende che…', ['sono i soluti a muovere l\'acqua, che li segue passivamente', 'è l\'acqua a trascinare i soluti attraverso la membrana', 'l\'acqua si muove indipendentemente dai soluti', 'l\'acqua si muove solo grazie a pompe attive'], 'Raggruppando K_osm, σ, R e T in un unico coefficiente di permeabilità all\'acqua si vede che la forza spingente è la differenza di concentrazione del soluto.', { p: 1 });
  A('07', 'Osmometro', 'In un osmometro da laboratorio, la pressione osmotica si misura…', ['dal dislivello, cioè dalla pressione idrostatica che annulla l\'osmosi', 'dalla variazione di temperatura della soluzione nel tempo', 'dalla velocità di diffusione del soluto nella soluzione', 'dal numero di particelle che attraversano la membrana'], 'Applicando una contropressione uguale a Δπ il flusso netto di acqua si azzera. L\'acqua che entra diluisce la soluzione e fa calare π nel tempo.');
  A('07', 'Attenzione slide', 'Il valore «1 Osm = 22,4 atmosfere» è corretto…', ['solo a 0 °C; a 37 °C sono circa 25,4 atm', 'a qualsiasi temperatura', 'solo a 37 °C, la temperatura corporea', 'solo per soluzioni di NaCl'], 'π = R·T·C: con R = 0,0821 L·atm/(K·mol) a 273 K si ha 22,4 atm, a 310 K si ha 25,4 atm.');

  // ======================================================================= 08 — Osmosi nella cellula e regolazione del volume
  A('08', 'Eritrocita', 'Un eritrocita in soluzione iperosmotica rispetto al citoplasma (> 300 mOsm)…', ['perde acqua e si raggrinzisce', 'guadagna acqua e si rigonfia', 'mantiene il disco biconcavo', 'guadagna acqua fino a lisi'], 'In soluzione isosmotica (300 mOsm) il flusso netto è nullo e la cellula resta un disco biconcavo; in soluzione iposmotica si rigonfia e può scoppiare lasciando «ghost» di membrana.', { p: 1 });
  A('08', 'Eritrocita', 'Perché un eritrocita in soluzione fortemente iposmotica va incontro a emolisi?', ['L\'ingresso d\'acqua supera la capacità di distensione della membrana', 'La membrana perde i suoi lipidi per diluizione', 'Le acquaporine si chiudono bloccando l\'uscita', 'Il citoplasma diventa ipertonico rispetto all\'esterno'], 'La membrana non si distende oltre circa il 3–4%: la cellula diventa una sfera e a ~140–150 mOsm (NaCl ≈ 0,45%) si ha lisi.');
  A('08', 'Tonicità', 'Una soluzione di urea 300 mM, isosmotica con il citoplasma, in cui un eritrocita…', ['si gonfia ed emolizza, perché l\'urea è permeante', 'resta normale, perché le osmolarità sono uguali', 'si raggrinzisce, perché l\'urea richiama acqua', 'si gonfia ma poi torna al volume iniziale'], 'L\'urea attraversa la membrana (σ ≈ 0) e viene seguita dall\'acqua. Isosmotica non significa isotonica: solo i soluti che non attraversano la membrana spostano acqua in modo duraturo.', { p: 1 });
  A('08', 'Acquaporine', 'Le acquaporine, aumentando la permeabilità all\'acqua, cambiano…', ['la velocità con cui la cellula raggiunge l\'equilibrio', 'il volume finale di equilibrio della cellula', 'l\'osmolarità della soluzione esterna', 'la direzione del flusso osmotico'], 'L\'equilibrio è lo stesso, ma si raggiunge molto più in fretta.');
  A('08', 'Regolazione del volume', 'Una cellula in ambiente ipotonico, che si sta gonfiando, attiva la risposta…', ['RVD: espelle soluti e l\'acqua li segue', 'RVI: importa soluti e l\'acqua li segue', 'RVD: importa acqua tramite acquaporine', 'RVI: espelle acqua con una pompa attiva'], 'RVD = Regulatory Volume Decrease; RVI = Regulatory Volume Increase (in ambiente ipertonico: la cellula importa sali con trasportatori e l\'acqua entra passivamente).', { p: 1 });
  A('08', 'Regolazione del volume', 'Quali ioni sono principalmente coinvolti nelle risposte di regolazione del volume?', ['K⁺, Cl⁻, H⁺ e Na⁺', 'Ca²⁺ e Mg²⁺ soltanto', 'HCO₃⁻ e fosfato soltanto', 'Fe²⁺ e Zn²⁺'], 'Ma anche segnali di membrana, citoscheletro ed espressione genica: lo scambio di acqua e soluti tra LIC e LEC va mantenuto in omeostasi e costa energia.');
  A('08', 'Osmolarità interna', 'Se una molecola di glicogeno viene idrolizzata in centinaia di molecole di glucosio, la pressione osmotica interna…', ['aumenta, perché aumenta il numero di particelle', 'diminuisce, perché le molecole sono più piccole', 'non cambia, perché la massa è la stessa', 'diventa nulla'], 'La pressione osmotica dipende dal numero di particelle, non dalla massa: un grande polimero conta come una sola particella.', { p: 1 });
  A('08', 'Osmocettori', 'Se l\'organismo perde acqua, gli osmocettori ipotalamici…', ['si raggrinziscono, cambiano la scarica e inducono il rilascio di ADH', 'si rigonfiano e riducono la secrezione di ADH', 'restano invariati, perché sono cellule non eccitabili', 'rilasciano direttamente aldosterone'], 'L\'ADH (vasopressina) raggiunge i tubuli renali e fa inserire acquaporine: si riassorbe acqua e si produce poca urina concentrata.', { p: 1 });
  A('08', 'Osmoregolazione', 'Gli invertebrati marini «osmoconformi»…', ['hanno osmolarità interna che segue quella dell\'ambiente', 'mantengono un\'osmolarità interna indipendente dall\'ambiente', 'sono tipici degli organismi terrestri', 'regolano il volume solo con la sete'], 'Gli organismi d\'acqua dolce, marini e terrestri più evoluti sono invece osmoregolatori.');

  // ======================================================================= 09 — Canali ionici e acquaporine
  A('09', 'Definizione', 'Che cos\'è un canale ionico?', ['Una proteina integrale di membrana con un poro idrofilo', 'Un poro scavato direttamente nel doppio strato lipidico', 'Una proteina periferica che lega gli ioni sulla superficie', 'Un trasportatore che cambia conformazione a ogni ione'], 'La prof insiste: molti studenti sbagliano la definizione di base. Il punto di partenza è sempre «proteina integrale di membrana»; il poro interno è idrofilo e lascia passare ioni inorganici.', { p: 2 });
  A('09', 'Subunità', 'Quale struttura è tipica dei recettori-canale (canali chemio-dipendenti)?', ['Cinque subunità disposte attorno al poro', 'Quattro subunità o domini attorno al poro', 'Sei connessine che formano un emicanale', 'Un\'unica elica transmembrana'], 'Quattro subunità o domini: canali voltaggio-dipendenti (Na⁺, K⁺). Sei connessine: connessoni delle gap junction.', { p: 1 });
  A('09', 'Selettività', 'La «selettività fine» di un canale consiste nel…', ['discriminare la singola specie ionica con il filtro di selettività', 'distinguere solo i cationi dagli anioni', 'lasciar passare tutte le molecole di piccole dimensioni', 'aprirsi solo in risposta a un ligando specifico'], 'La selettività grezza distingue soltanto per carica (cationi/anioni). Il filtro ha una «taglia» che dipende dal raggio dello ione e dal suo guscio di idratazione.', { p: 1 });
  A('09', 'Gating', 'Con il termine «gating» si indica…', ['la stabilizzazione del canale in conformazione aperta o chiusa', 'la capacità di scegliere lo ione che passa nel poro', 'la velocità con cui gli ioni attraversano il poro', 'il flusso netto di ioni a canale aperto'], 'Aperto = pervio, chiuso = impervio. Le proteine oscillano per agitazione termica; il gating è la stabilizzazione in una conformazione da parte di fattori regolatori (voltaggio, ligandi, stiramento).', { p: 1 });
  A('09', 'Gating', 'Quali sono i tre principali meccanismi di gating dei canali ionici?', ['Voltaggio-dipendente, chemio-dipendente, meccano-dipendente', 'Voltaggio-dipendente, termo-dipendente, pH-dipendente', 'Chemio-dipendente, osmo-dipendente, fotodipendente', 'Meccano-dipendente, ATP-dipendente, ormono-dipendente'], 'Il gating chemio-dipendente può essere regolato da un ligando extracellulare (neurotrasmettitori, ormoni) o intracellulare (secondi messaggeri, ioni, ATP).', { p: 1 });
  A('09', 'Canali di leakage', 'I canali di leakage (di fuga) sono canali…', ['privi di gating, sempre aperti e presenti in tutte le membrane', 'con gating, che si aprono solo se depolarizzati', 'presenti solo nelle cellule eccitabili', 'aperti solo in presenza di un ligando specifico'], 'Sono vitali e funzionalmente accoppiati ai trasporti attivi.', { p: 1 });
  A('09', 'Canali di leakage', 'Perché i canali di leakage non cancellano i gradienti ionici della cellula?', ['I flussi passivi sono bilanciati dai trasporti attivi che consumano ATP', 'Il flusso attraverso di essi è sempre trascurabile', 'Funzionano solo quando il gradiente è già nullo', 'Lasciano passare soltanto ioni a carica zero'], 'Nelle condizioni fisiologiche la diffusione è compensata da un trasporto attivo che riporta lo ione dov\'era: «l\'equilibrio è gratis, ma gli organismi viventi non vogliono l\'equilibrio».', { p: 1 });
  A('09', 'Canale del sodio', 'Nel canale del Na⁺ voltaggio-dipendente, il sensore del voltaggio è…', ['l\'elica S4, ricca di amminoacidi con carica positiva', 'l\'ansa fra S5 e S6, ricca di amminoacidi apolari', 'l\'estremità N-terminale intracellulare', 'l\'elica S1, formata da amminoacidi acidi'], 'Il canale è un\'unica catena con 4 domini (I–IV), ciascuno con 6 α-eliche (S1–S6). Il filtro di selettività è nell\'ansa tra S5 e S6.', { p: 1 });
  A('09', 'Canale del sodio', 'Il canale del Na⁺ voltaggio-dipendente differisce da quello del K⁺ perché…', ['è una sola catena con 4 domini, mentre il K⁺ è formato da 4 subunità distinte', 'è formato da 4 subunità separate, mentre il K⁺ è una sola catena', 'ha 6 subunità mentre il K⁺ ne ha 4', 'ha un solo dominio mentre il K⁺ ne ha 4'], 'Il canale del K⁺ può essere un omotetramero (subunità identiche) o un eterotetramero (subunità diverse, da geni o splicing diversi).', { p: 1 });
  A('09', 'Canale del sodio', 'Quanti stati conformazionali ha il canale del Na⁺ voltaggio-dipendente?', ['Tre: aperto, chiuso e inattivato', 'Due: aperto e chiuso', 'Quattro: aperto, chiuso, inattivato e rigenerato', 'Uno solo: sempre aperto'], 'Lo stato chiuso e quello inattivato sono entrambi impervi, ma sono stati molecolari distinti.', { p: 1 });
  A('09', 'Cooperatività', 'Nella cellula β pancreatica, l\'aumento di ATP provoca…', ['la chiusura dei canali K_ATP e quindi la depolarizzazione', 'l\'apertura dei canali K_ATP e quindi l\'iperpolarizzazione', 'l\'apertura diretta dei canali del Ca²⁺ per legame di ATP', 'la chiusura dei canali del Ca²⁺ voltaggio-dipendenti'], 'Glucosio ↑ → ATP ↑ → K_ATP chiusi → depolarizzazione → apertura dei canali Ca²⁺ voltaggio-dipendenti → ingresso di Ca²⁺ → esocitosi dei granuli di insulina. È un esempio di cooperatività tra due popolazioni di canali.', { p: 1 });
  A('09', 'Cooperatività', 'Le sulfoniluree, farmaci usati nel diabete, favoriscono la secrezione di insulina…', ['chiudendo i canali K_ATP', 'aprendo i canali K_ATP', 'bloccando i canali del Ca²⁺', 'aumentando la glicemia'], 'Mimano l\'effetto dell\'ATP sui K_ATP: depolarizzazione, ingresso di Ca²⁺ e secrezione di insulina anche a glicemia non elevata.');
  A('09', 'Conduttanza', 'In un canale aperto passano circa 10⁶ ioni al secondo; la corrente di un singolo canale è quindi dell\'ordine…', ['dei picoampere (pA)', 'dei milliampere (mA)', 'degli ampere (A)', 'dei nanoampere (nA)'], 'Si misura con la tecnica del patch clamp.');
  A('09', 'Acquaporine', 'Rispetto alla diffusione attraverso il doppio strato, le acquaporine…', ['abbattono l\'energia di attivazione e accelerano un flusso sempre passivo', 'trasportano acqua contro gradiente con consumo di ATP', 'trasportano acqua solo in entrata nella cellula', 'sono sempre aperte ma poco selettive per l\'acqua'], 'Il passaggio dell\'acqua dalla tela lipidica ha un\'altissima energia di attivazione. Con le acquaporine il flusso è passivo, bidirezionale e fino a 100 volte più rapido.', { p: 1 });
  A('09', 'Acquaporine', 'La peculiarità delle acquaporine rispetto ad altri canali tetramerici è che…', ['ogni subunità ha il proprio poro acquoso indipendente', 'hanno un unico poro centrale formato dalle 4 subunità', 'funzionano solo come dimeri', 'non hanno il motivo conservato NPA'], 'Il tetramero ha quindi 4 vie di permeazione. Ogni subunità ha 6 eliche; le anse con il motivo NPA (Asn-Pro-Ala) formano il filtro per l\'acqua.', { p: 1 });
  A('09', 'Acquaporine', 'Quale esperimento di Peter Agre dimostrò la funzione dell\'AQP1?', ['Oociti di Xenopus con AQP1 in soluzione iposmotica si gonfiano e scoppiano', 'Eritrociti privi di AQP1 si gonfiano più rapidamente', 'Oociti di Xenopus con AQP1 si raggrinziscono in soluzione ipertonica', 'Neuroni con AQP1 emettono potenziali d\'azione più rapidi'], 'È un esperimento di espressione eterologa: la proteina conferisce permeabilità idrica. Agre ha vinto il Nobel per la Chimica nel 2003.', { p: 1 });
  A('09', 'Acquaporine', 'L\'acquaporina 2 (AQP2)…', ['sta sul lato apicale del dotto collettore ed è regolata dall\'ADH', 'è nei globuli rossi ed è regolata dall\'insulina', 'sta nel cristallino e non è regolata da ormoni', 'è nelle ghiandole salivari ed è regolata dal cortisolo'], 'L\'ADH sale su un recettore, aumenta il cAMP e induce l\'esocitosi di vescicole con AQP2 nella membrana apicale: antidiuresi. AQP3 sta sul lato basolaterale; AQP1 è nel globulo rosso e in altri tessuti (anche nel rene).', { p: 1 });
  A('09', 'Diabete insipido', 'Nel diabete insipido, a differenza del diabete mellito…', ['l\'urina abbondante non contiene glucosio', 'l\'urina abbondante contiene molto glucosio', 'l\'urina è scarsa e molto concentrata', 'la sete è assente'], 'Cause: carenza di ADH, mutazione dell\'ADH o del suo recettore, difetti della cascata, mutazione di AQP2 (non arriva alla membrana apicale). Si ha poliuria con grave sete (polidipsia).', { p: 1 });
  A('09', 'Famiglia AQP', 'Le acquagliceroporine (per esempio AQP3, AQP7, AQP9) fanno passare…', ['acqua, glicerolo e piccoli soluti neutri', 'esclusivamente acqua pura', 'acqua e ioni Na⁺ in cotrasporto', 'glicerolo, ma non acqua liquida'], 'Le acquaporine «pure» (AQP1, 2, 4, 5) fanno passare soltanto acqua.');

  //__L10__
})(typeof globalThis !== 'undefined' ? globalThis : this);
